function key(uid,kind){return `central-v6:${kind}:${uid}`}
function goalDone(uid){return localStorage.getItem(key(uid,'done'))==='1'}
function setDone(uid,v){localStorage.setItem(key(uid,'done'),v?'1':'0')}
function subjStats(s){
 if(s.id==='pt'){
   const total=PT_CONFIG.weeks.length*7;
   let done=0;
   PT_CONFIG.weeks.forEach(w=>w.days.forEach(d=>{if(ptDayDone(w.week,d.day))done++}));
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'dias'};
 }
 if(s.id==='cf'){
   const total=CF_WEEKS.length,done=CF_WEEKS.filter(w=>cfWeekPct(w)===100).length;
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'módulos'};
 }
 if(s.id==='penal'){
   const total=PENAL_WEEKS.length,done=PENAL_WEEKS.filter(w=>penalWeekPct(w)===100).length;
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'módulos'};
 }
 if(s.id==='cpc'){
   const total=CPC_WEEKS.length,done=CPC_WEEKS.filter(w=>cpcWeekPct(w)===100).length;
   return {total,done,pct:total?Math.round(done/total*100):0,unit:'módulos'};
 }
 if(s.id==='civil'){
   const st=civilCourseStats();return {total:st.total,done:st.done,pct:st.pct,unit:'módulos'};
 }
 const total=s.topics.length,done=s.topics.filter(t=>goalDone(t.uid)).length;
 return {total,done,pct:total?Math.round(done/total*100):0,unit:(s.id==='trab'||s.id==='ptra')?'aulas':'metas'};
}
function toggleSubject(id){const el=document.querySelector(`.subject[data-id="${id}"]`);const o=!el.classList.contains('open');el.classList.toggle('open');localStorage.setItem(`central-v6:open:${id}`,o?'1':'0')}
function toggleGoal(uid,v,e){e?.stopPropagation();setDone(uid,v);renderAll()}
function topicOpenKey(uid){return `central-v6:topic-open:${uid}`}
function toggleTopic(uid){
 const el=document.querySelector(`.topic-item[data-uid="${uid}"]`);
 if(!el)return;
 const opening=!el.classList.contains('open');
 el.classList.toggle('open',opening);
 localStorage.setItem(topicOpenKey(uid),opening?'1':'0');
 if(opening)saveLastTopic(uid);
}
function topicByUid(uid){for(const s of SUBJECTS){const t=s.topics.find(x=>x.uid===uid);if(t)return {s,t}}return null}

function saveLastTopic(uid){const x=topicByUid(uid);if(x)saveLast({topicUid:uid,title:x.s.name+' • '+x.t.title,at:Date.now()})}
function saveLast(x){localStorage.setItem('central-v6:last',JSON.stringify(x));renderContinue()}
function openPtLast(week,day){
 openHome();
 localStorage.setItem('central-v6:open:pt','1');
 localStorage.setItem(ptWeekOpenKey(week),'1');
 localStorage.setItem(ptDayOpenKey(week,day),'1');
 setTimeout(()=>{
   renderSubjects();
   document.querySelector(`.pt-day[data-daykey="${week}-${day}"]`)?.scrollIntoView({behavior:'smooth',block:'center'});
 },40);
}
function renderContinue(){const x=JSON.parse(localStorage.getItem('central-v6:last')||'null');if(!x){$('continueBox').innerHTML='<div class="muted small">Nenhuma sessão recente.</div>';return}const act=x.tool==='vade-mecum'?`openVadeMecum()`:x.tool==='lei-seca-enxuta'?`openLeiSecaEnxuta()`:x.civilModule?`openCivilLast('${x.civilModule}')`:x.cfWeek?`openCfLast('${x.cfWeek}')`:x.penalWeek?`openPenalLast('${x.penalWeek}')`:x.cpcWeek?`openCpcLast('${x.cpcWeek}')`:x.ptWeek?`openPtLast(${x.ptWeek},${x.ptDay})`:x.topicUid?`openTopicFromLast('${x.topicUid}')`:`openInternal('${escJs(x.url)}','${escJs(x.title)}')`;$('continueBox').innerHTML=`<b style="display:block;font-size:12px">${esc(x.title)}</b><span class="muted small">${new Date(x.at).toLocaleString('pt-BR')}</span><div style="margin-top:9px"><button class="btn primary sm" onclick="${act}">Continuar</button></div>`}
function openTopicFromLast(uid){openHome();setTimeout(()=>{const found=topicByUid(uid);if(found){localStorage.setItem(`central-v6:open:${found.s.id}`,'1');renderSubjects();localStorage.setItem(topicOpenKey(uid),'1');renderSubjects();const el=document.querySelector(`.topic-item[data-uid="${uid}"]`);el?.scrollIntoView({behavior:'smooth',block:'center'})}},30)}

function renderSubjects(){
 $('subjects').innerHTML=SUBJECTS.map(s=>{
  const st=subjStats(s),open=localStorage.getItem(`central-v6:open:${s.id}`)==='1';
  const unit=s.id==='pt'?'dias':(s.id==='cf'||s.id==='civil'||s.id==='penal'||s.id==='cpc')?'módulos':'metas';
  return `<section class="subject ${open?'open':''}" data-id="${s.id}">
   <button class="subject-head" onclick="toggleSubject('${s.id}')"><span class="subject-name">${esc(s.name)}</span><span class="subject-count">${st.done}/${st.total} ${unit}</span><span class="subject-pct ${st.pct===100?'done':''}">${st.pct}%</span><span class="chev">⌄</span></button>
   <div class="subject-body"><div class="subject-bar"><span style="width:${st.pct}%"></span></div>
    ${s.id==='pt' ? renderPortugueseMaster() : s.id==='cf' ? renderConstitutionalMaster() : s.id==='penal' ? renderPenalMaster() : s.id==='cpc' ? renderCpcMaster() : s.id==='civil' ? renderCivilMaster() : `
      <div class="topic-header"><div></div><div>Tópico real</div><div>Origem</div><div>Tipo</div><div></div></div>
      ${s.topics.map(t=>renderTopic(s,t)).join('')}
    `}
   </div>
  </section>`;
 }).join('')
}




const CIVIL_STORAGE_KEY='central-v6:civil-course-v1';
let civilUi={stage:null,index:0};

function civilFresh(){return {modules:{m1:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m2:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m3:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m4:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m5:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m6:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m7:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m8:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m9:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m10:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m11:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m12:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m13:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m14:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m15:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false},m16:{reading:false,theory:false,deep:false,errorsReviewed:false,anki:false}},answers:{}}}
function civilState(){try{const x=JSON.parse(localStorage.getItem(CIVIL_STORAGE_KEY)||'{}');return {...civilFresh(),...x,modules:{...civilFresh().modules,...(x.modules||{})},answers:x.answers||{}}}catch(e){return civilFresh()}}
function civilSave(st){localStorage.setItem(CIVIL_STORAGE_KEY,JSON.stringify(st))}
function civilModuleState(id='m1'){const st=civilState();return {...(civilFresh().modules[id]||{}),...(st.modules?.[id]||{})}}
function civilSetModule(id,patch){const st=civilState();st.modules=st.modules||{};st.modules[id]={...(st.modules[id]||{}),...patch};civilSave(st);renderAll()}
function civilAnswer(id){return civilState().answers?.[id]||null}
function civilStageQuestions(stage){
 if(stage==='diagnostic')return CIVIL_COURSE.diagnostic;
 if(stage==='final')return CIVIL_COURSE.final;
 if(stage==='cases')return CIVIL_COURSE.cases;
 if(stage==='errors'){
   const all=[...CIVIL_COURSE.diagnostic,...CIVIL_COURSE.cases,...CIVIL_COURSE.final];
   return all.filter(q=>civilAnswer(q.id)?.everWrong);
 }
 return[];
}
function civilAnsweredCount(stage){return civilStageQuestions(stage).filter(q=>(civilAnswer(q.id)?.attempts||0)>0).length}
function civilStageDone(stage){
 const qs=civilStageQuestions(stage);return qs.length>0&&qs.every(q=>(civilAnswer(q.id)?.attempts||0)>0)
}
function civilSteps(){
 const m=civilModuleState('m1');
 return [
  {id:'diagnostic',done:civilStageDone('diagnostic')},
  {id:'reading',done:!!m.reading},
  {id:'theory',done:!!m.theory},
  {id:'deep',done:!!m.deep},
  {id:'cases',done:civilStageDone('cases')},
  {id:'final',done:civilStageDone('final')},
  {id:'errors',done:!!m.errorsReviewed},
  {id:'anki',done:!!m.anki}
 ]
}
function civilModulePct(id){
 let a;
 if(id==='m1')a=civilSteps();
 else if(id==='m2')a=civil2Steps();
 else if(id==='m3')a=civil3Steps();
 else if(id==='m4')a=civil4Steps();
 else if(id==='m5')a=civil5Steps();
 else if(id==='m6')a=civil6Steps();
 else if(id==='m7')a=civil7Steps();
 else if(id==='m8')a=civil8Steps();
 else if(id==='m9')a=civil9Steps();
 else if(id==='m10')a=civil10Steps();
 else if(id==='m11')a=civil11Steps();
 else if(id==='m12')a=civil12Steps();
 else if(id==='m13')a=civil13Steps();
 else if(id==='m14')a=civil14Steps();
 else if(id==='m15')a=civil15Steps();
 else if(id==='m16')a=civil16Steps();
 else return 0;
 return Math.round(a.filter(x=>x.done).length/a.length*100)
}
function civilCourseStats(){
 const total=CIVIL_COURSE.modules.length;
 const done=CIVIL_COURSE.modules.filter(m=>m.status==='active'&&civilModulePct(m.id)===100).length;
 return {total,done,pct:Math.round(done/total*100)}
}
function civilModuleOpenKey(id){return `central-v6:civil-open:${id}`}
function civilStepOpenKey(id){return `central-v6:civil-step:m1:${id}`}
function toggleCivilModule(id){
 const el=document.querySelector(`.civil-module[data-civil="${id}"]`);if(!el)return;
 const open=!el.classList.contains('open');el.classList.toggle('open',open);localStorage.setItem(civilModuleOpenKey(id),open?'1':'0');
 if(open&&id==='m1')saveLast({civilModule:'m1',title:'Direito Civil • Módulo 1 • Pessoa Natural',at:Date.now()})
}
function toggleCivilStep(id){
 const el=document.querySelector(`.civil-step[data-step="${id}"]`);if(!el)return;
 const open=!el.classList.contains('open');el.classList.toggle('open',open);localStorage.setItem(civilStepOpenKey(id),open?'1':'0')
}
function openCivilLast(id='m1'){
 openHome();localStorage.setItem('central-v6:open:civil','1');localStorage.setItem(civilModuleOpenKey(id),'1');
 setTimeout(()=>{renderSubjects();document.querySelector(`.civil-module[data-civil="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})},40)
}
function civilOpenStage(stage){
 const qs=civilStageQuestions(stage);if(!qs.length){civilUi={stage,index:0};renderSubjects();return}
 let idx=qs.findIndex(q=>(civilAnswer(q.id)?.attempts||0)===0);if(idx<0)idx=0;
 civilUi={stage,index:idx};localStorage.setItem(civilStepOpenKey(stage),'1');renderSubjects();
 setTimeout(()=>document.querySelector(`.civil-step[data-step="${stage}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),20)
}
function civilSelect(id,letter){
 const st=civilState(),a=st.answers[id]||{attempts:0,history:[],everWrong:false};
 if(a.submitted)return;
 a.selected=letter;a.submitted=false;st.answers[id]=a;civilSave(st);renderSubjects()
}
function civilSubmit(id,stage){
 const q=[...CIVIL_COURSE.diagnostic,...CIVIL_COURSE.cases,...CIVIL_COURSE.final].find(x=>x.id===id);
 if(!q)return;const st=civilState(),a=st.answers[id]||{attempts:0,history:[],everWrong:false};
 if(!a.selected){alert('Escolha uma alternativa primeiro.');return}
 const correct=a.selected===q.answer;
 a.attempts=(a.attempts||0)+1;a.submitted=true;a.lastCorrect=correct;a.everWrong=!!a.everWrong||!correct;
 a.history=[...(a.history||[]),{at:new Date().toISOString(),selected:a.selected,correct,stage}];
 st.answers[id]=a;civilSave(st);renderAll()
}
function civilRetry(id){const st=civilState(),a=st.answers[id];if(!a)return;a.selected=null;a.submitted=false;st.answers[id]=a;civilSave(st);renderSubjects()}
function civilMove(stage,delta){
 const qs=civilStageQuestions(stage);if(!qs.length)return;
 civilUi.stage=stage;civilUi.index=Math.max(0,Math.min(qs.length-1,(civilUi.stage===stage?civilUi.index:0)+delta));renderSubjects()
}
function civilQuestionMeta(q){
 const role=/Oficial de Justiça/i.test(q.source)?'Oficial de Justiça':/AJ |Ana JD|Analista/i.test(q.source)?'Analista / carreira jurídica':'Carreira jurídica';
 return `<div class="civil-qmeta"><span class="civil-chip ${q.kind==='real'?'real':'authorial'}">${q.kind==='real'?'QUESTÃO REAL FCC':'AUTORAL'}</span><span class="civil-chip role">${esc(role)}</span><span class="civil-chip">${esc(q.basis)}</span><span class="civil-qsource">${esc(q.source)}</span></div>`
}
function civilQuestionCard(q,stage,index,total){
 const a=civilAnswer(q.id)||{selected:null,submitted:false,attempts:0,history:[]};
 const locked=!!a.submitted;
 const opts=Object.entries(q.options).map(([letter,text])=>{
   let cls='civil-option';if(a.selected===letter)cls+=' selected';
   if(locked&&letter===q.answer)cls+=' correct';else if(locked&&a.selected===letter&&letter!==q.answer)cls+=' wrong';
   return `<button class="${cls}" ${locked?'disabled':''} onclick="civilSelect('${escJs(q.id)}','${letter}')"><span class="civil-letter">${letter}</span><span>${esc(text)}</span></button>`
 }).join('');
 const feedback=locked?`<div class="civil-feedback ${a.lastCorrect?'good':'bad'}"><b>${a.lastCorrect?'✓ Resposta correta':'✕ Resposta incorreta — gabarito '+q.answer}</b>${esc(q.explanation)}<span class="basis">Fundamento: ${esc(q.basis)}${a.attempts>1?' · '+a.attempts+' tentativas':''}</span></div>`:'';
 return `<article class="civil-qcard">${civilQuestionMeta(q)}<h4>${esc(q.prompt)}</h4><div class="civil-options">${opts}</div>
  <div class="civil-submit-row"><div>${q.kind==='real'?`<a class="civil-source-link" href="${escAttr(q.url)}" target="_blank" rel="noopener">Fonte da questão no TEC ↗</a>`:'<span class="muted small">Caso criado para aplicação da regra.</span>'}</div>
   <div class="civil-qnav"><button class="civil-btn" onclick="civilMove('${stage}',-1)" ${index===0?'disabled':''}>←</button><span>${index+1} / ${total}</span><button class="civil-btn" onclick="civilMove('${stage}',1)" ${index===total-1?'disabled':''}>→</button></div>
   ${locked?`<button class="civil-btn" onclick="civilRetry('${escJs(q.id)}')">Refazer</button>`:`<button class="civil-btn primary" onclick="civilSubmit('${escJs(q.id)}','${stage}')">Responder</button>`}
  </div>${feedback}</article>`
}
function civilStageSession(stage){
 const qs=civilStageQuestions(stage);if(!qs.length)return '<div class="muted small">Nenhuma questão disponível.</div>';
 if(civilUi.stage!==stage)civilUi={stage,index:Math.max(0,qs.findIndex(q=>(civilAnswer(q.id)?.attempts||0)===0))};
 civilUi.index=Math.max(0,Math.min(qs.length-1,civilUi.index));return civilQuestionCard(qs[civilUi.index],stage,civilUi.index,qs.length)
}
function civilAccuracy(stage){
 const qs=civilStageQuestions(stage),answered=qs.map(q=>civilAnswer(q.id)).filter(a=>a?.attempts);
 const correct=answered.filter(a=>a.lastCorrect).length;return {answered:answered.length,total:qs.length,correct,pct:answered.length?Math.round(correct/answered.length*100):0}
}
function civilQuestionStep(stage,title,subtitle,num){
 const stats=civilAccuracy(stage),done=civilStageDone(stage),open=localStorage.getItem(civilStepOpenKey(stage))==='1';
 const active=civilUi.stage===stage;
 return `<section class="civil-step ${done?'done':''} ${open?'open':''}" data-step="${stage}">
  <button class="civil-step-head" onclick="toggleCivilStep('${stage}')"><span class="civil-step-n">${done?'✓':num}</span><span class="civil-step-title"><b>${esc(title)}</b><small>${esc(subtitle)}</small></span><span class="civil-step-status">${stats.answered}/${stats.total} respondidas${stats.answered?' · '+stats.pct+'%':''}</span><span>⌄</span></button>
  <div class="civil-step-body"><div class="civil-stage-toolbar"><p>${stage==='diagnostic'?'Faça primeiro sem consultar a teoria. O objetivo é medir sua base real.':stage==='final'?'Bateria posterior à teoria, com foco em nível superior e aplicação dos dispositivos.':'Casos novos para transformar a regra em decisão jurídica.'}</p><div class="civil-stage-actions"><button class="civil-btn primary" onclick="civilOpenStage('${stage}')">${stats.answered?'Continuar':'Iniciar'}</button></div></div>${active?civilStageSession(stage):''}</div></section>`
}
function civilManualStep(id,title,subtitle,num,body,field){
 const st=civilModuleState('m1'),done=!!st[field],open=localStorage.getItem(civilStepOpenKey(id))==='1';
 return `<section class="civil-step ${done?'done':''} ${open?'open':''}" data-step="${id}">
  <button class="civil-step-head" onclick="toggleCivilStep('${id}')"><span class="civil-step-n">${done?'✓':num}</span><span class="civil-step-title"><b>${esc(title)}</b><small>${esc(subtitle)}</small></span><span class="civil-step-status">${done?'Concluído':'Pendente'}</span><span>⌄</span></button>
  <div class="civil-step-body">${body}<label class="civil-manual-done"><input type="checkbox" ${done?'checked':''} onchange="civilSetModule('m1',{${field}:this.checked})"> Marcar esta etapa como concluída</label></div></section>`
}
function civilReadingBody(){
 return `<div class="civil-theory"><section><h4>Leitura orientada — não leia o Código inteiro sem direção</h4><div class="civil-law-grid">
  <div class="civil-law-card"><b>CC, arts. 1º a 5º</b><span>Personalidade, capacidade, incapacidade e emancipação.</span></div>
  <div class="civil-law-card"><b>CC, arts. 6º a 10</b><span>Morte, morte presumida, comoriência, registro e averbação.</span></div>
  <div class="civil-law-card"><b>CC, arts. 22 a 39</b><span>Ausência: curadoria, sucessão provisória e sucessão definitiva.</span></div>
 </div><p><strong>Complemento obrigatório:</strong> Lei 13.146/2015 (LBI), art. 6º, para não confundir deficiência com incapacidade.</p>
 <div class="civil-stage-actions"><button class="civil-btn primary" onclick="saveLast({civilModule:'m1',title:'Direito Civil • Módulo 1 • Leitura no Vade Mecum',at:Date.now()});openVadeMecum(null,'cc')">📖 Abrir Código Civil no Vade Mecum</button></div>
 <div class="civil-alert">Neste módulo, pare no art. 10 e depois salte para os arts. 22 a 39. <b>Direitos da Personalidade (arts. 11 a 21) ficam para o Módulo 2</b>, para não misturar os blocos.</div></section></div>`
}
function civilTheoryBody(){
 return `<div class="civil-theory">
 <section><h4>1. Personalidade civil e nascituro</h4><p><strong>Toda pessoa é capaz de direitos e deveres na ordem civil.</strong> A personalidade civil começa com o nascimento com vida. O art. 2º, porém, protege desde a concepção os direitos do nascituro.</p><p>Para prova objetiva, não confunda os marcos: <strong>concepção protege direitos do nascituro; nascimento com vida inicia a personalidade civil; registro apenas documenta o nascimento.</strong></p></section>
 <section><h4>2. Capacidade de direito × capacidade de fato</h4><table class="civil-compare"><tr><th>Capacidade de direito</th><th>Capacidade de fato/exercício</th></tr><tr><td>Aptidão para ser titular de direitos e deveres. É atributo de toda pessoa.</td><td>Aptidão para exercer pessoalmente os atos da vida civil. Pode sofrer limitações por incapacidade.</td></tr></table></section>
 <section><h4>3. Incapacidade no regime atual</h4><ul><li><strong>Absoluta:</strong> somente menores de 16 anos (art. 3º). Atuam por representação.</li><li><strong>Relativa:</strong> maiores de 16 e menores de 18; ébrios habituais e viciados em tóxico; quem não puder exprimir vontade por causa transitória ou permanente; pródigos (art. 4º). A prática do ato exige a forma de assistência/proteção cabível.</li><li><strong>Indígenas:</strong> a capacidade é regulada por legislação especial.</li></ul><div class="civil-alert">Pegadinha recorrente: deficiência mental ou intelectual <b>não é, por si só, hipótese de incapacidade</b>. Após a LBI, verifique se a pessoa se enquadra concretamente em uma hipótese do art. 4º.</div></section>
 <section><h4>4. Emancipação</h4><p>A maioridade chega aos 18 anos, mas a incapacidade do menor pode cessar antes.</p><table class="civil-compare"><tr><th>Espécie</th><th>Requisitos centrais</th></tr>
 <tr><td>Voluntária</td><td>Concessão dos pais (ou de um na falta do outro), menor com 16 anos completos, <strong>instrumento público</strong>, sem homologação judicial.</td></tr>
 <tr><td>Judicial</td><td>Sentença do juiz, ouvido o tutor, para menor com 16 anos completos.</td></tr>
 <tr><td>Legal</td><td>Casamento; emprego público efetivo; colação de grau em curso superior; estabelecimento civil/comercial ou relação de emprego com 16+ e economia própria.</td></tr></table>
 <p>Ocorrida uma causa válida, o menor passa a ter capacidade civil plena. Isso não transforma sua idade cronológica nem afasta automaticamente regras especiais baseadas em idade.</p></section>
 <section><h4>5. Fim da pessoa natural, morte presumida e comoriência</h4><ul><li>A existência da pessoa natural termina com a morte.</li><li><strong>Morte presumida sem ausência:</strong> extrema probabilidade de morte de quem estava em perigo de vida; ou desaparecimento em campanha/prisioneiro não encontrado até dois anos após o término da guerra.</li><li>Nas hipóteses do art. 7º, é necessário esgotar buscas e averiguações, e a sentença fixa a data provável do falecimento.</li><li><strong>Comoriência:</strong> mortos na mesma ocasião sem prova da ordem → presunção de mortes simultâneas.</li></ul></section>
 <section><h4>6. Registro e averbação — arts. 9º e 10</h4><p>O art. 9º prevê registro público de nascimentos, casamentos, óbitos, emancipação parental/judicial, interdição e sentença declaratória de ausência e de morte presumida. O art. 10 trata, entre outros pontos, da averbação de decisões sobre estado conjugal e dos atos que reconhecem filiação.</p><div class="civil-alert">Não troque <b>fato constitutivo</b> por <b>registro</b>: a personalidade nasce com vida; o registro não cria a personalidade.</div></section>
 <section><h4>7. Ausência — três fases que precisam estar separadas na cabeça</h4><table class="civil-compare"><tr><th>Fase</th><th>Regra essencial</th></tr>
 <tr><td>Curadoria dos bens</td><td>Desaparecimento sem notícia e sem representante apto; também se o mandatário não quiser, não puder ou tiver poderes insuficientes. O juiz declara ausência e nomeia curador.</td></tr>
 <tr><td>Sucessão provisória</td><td>Em regra, 1 ano após arrecadação dos bens; 3 anos se havia representante/procurador. A sentença produz efeitos 180 dias após publicação.</td></tr>
 <tr><td>Sucessão definitiva</td><td>Regra: 10 anos após trânsito em julgado da sentença de sucessão provisória. Regra especial: ausente com 80 anos + últimas notícias há 5 anos.</td></tr></table>
 <p><strong>Curador preferencial:</strong> cônjuge não separado judicialmente nem de fato por mais de 2 anos; depois pais; depois descendentes; na falta, escolha judicial.</p><p><strong>Garantia na posse provisória:</strong> regra é garantia de restituição, mas ascendentes, descendentes e cônjuge, comprovada a qualidade de herdeiro, entram sem garantia.</p></section>
 </div>`
}
function civilDeepBody(){
 return `<div class="civil-theory">
 <section class="civil-juris"><h4>Aprofundamento 1 — emancipação legal por emprego (STJ)</h4><p>O STJ, no REsp 1.872.102/SP (Informativo 687), tratou da emancipação decorrente da relação de emprego. Para essa hipótese, destacou três requisitos objetivos: <strong>16 anos completos + vínculo empregatício + economia própria</strong>.</p><p>Preenchidos os requisitos, a emancipação legal decorre da lei e prescinde de autorização judicial; o STJ também registrou que não é o registro público que condiciona a validade dos atos civis praticados pelo emancipado.</p></section>
 <section class="civil-juris"><h4>Aprofundamento 2 — deficiência não é sinônimo de incapacidade</h4><p>A Lei Brasileira de Inclusão rompeu a associação automática entre deficiência e incapacidade civil. O art. 6º estabelece que a deficiência não afeta a plena capacidade civil, inclusive para casar e constituir união estável.</p><p>Em prova: primeiro identifique a <strong>hipótese legal de incapacidade</strong>. Uma pessoa com deficiência pode ser plenamente capaz; se não puder exprimir a vontade, a classificação decorre do art. 4º, III, e não do diagnóstico em si.</p></section>
 <section><h4>Mapa de pegadinhas de nível superior</h4><table class="civil-compare"><tr><th>Pegadinha</th><th>Correção</th></tr>
 <tr><td>“Nascituro já tem personalidade civil plena.”</td><td>O CC fixa o nascimento com vida como início da personalidade, preservando direitos desde a concepção.</td></tr>
 <tr><td>“Toda incapacidade mental é absoluta.”</td><td>Não. Absoluta, no CC atual, apenas para menor de 16 anos.</td></tr>
 <tr><td>“Emancipação parental exige homologação.”</td><td>Não. Exige instrumento público e 16 anos completos.</td></tr>
 <tr><td>“Qualquer emprego emancipa.”</td><td>Não. Na hipótese do art. 5º, V, exige 16+ e economia própria.</td></tr>
 <tr><td>“Morte presumida sempre depende de ausência.”</td><td>Não. O art. 7º prevê hipóteses sem decretação de ausência.</td></tr>
 <tr><td>“Na comoriência, morre primeiro o mais velho.”</td><td>Sem prova da ordem, presume-se morte simultânea.</td></tr>
 <tr><td>“Se existe procurador, não há ausência.”</td><td>Pode haver se o mandatário não quiser, não puder ou tiver poderes insuficientes.</td></tr></table></section>
 </div>`
}
function civilErrorStep(){
 const id='errors',m=civilModuleState('m1'),done=!!m.errorsReviewed,open=localStorage.getItem(civilStepOpenKey(id))==='1';
 const qs=civilStageQuestions('errors'),unresolved=qs.filter(q=>civilAnswer(q.id)?.lastCorrect===false);
 const rows=qs.map(q=>{const a=civilAnswer(q.id);return `<div class="civil-error-row"><div><b>${q.kind==='real'?'FCC':'Autoral'} • ${esc(q.subject)}</b><small>${a?.lastCorrect?'Corrigida na última tentativa':'Ainda errada na última tentativa'} · ${a?.attempts||0} tentativa(s)</small></div><button class="civil-btn" onclick="civilUi={stage:'errors',index:${qs.indexOf(q)}};localStorage.setItem(civilStepOpenKey('errors'),'1');renderSubjects()">Revisar</button></div>`}).join('');
 return `<section class="civil-step ${done?'done':''} ${open?'open':''}" data-step="errors"><button class="civil-step-head" onclick="toggleCivilStep('errors')"><span class="civil-step-n">${done?'✓':'7'}</span><span class="civil-step-title"><b>Revisão de erros</b><small>Volte apenas nas questões em que você já errou.</small></span><span class="civil-step-status">${qs.length} no histórico · ${unresolved.length} ainda erradas</span><span>⌄</span></button>
 <div class="civil-step-body">${qs.length?`<div class="civil-error-list">${rows}</div>${civilUi.stage==='errors'?`<div style="margin-top:9px">${civilStageSession('errors')}</div>`:''}`:'<div class="muted small">Nenhum erro registrado ainda. Esta lista será criada automaticamente conforme você responder.</div>'}
 <label class="civil-manual-done"><input type="checkbox" ${done?'checked':''} onchange="civilSetModule('m1',{errorsReviewed:this.checked})"> Marcar minha revisão de erros como concluída</label></div></section>`
}
